import json, sys

errors = []

# 1) JSON validity + exact schema
with open('sessao5/garantia.json', encoding='utf-8') as f:
    raw = f.read()
d = json.loads(raw)

expected_top = {"valor_remanescente_atualizado","seguro_garantia","fianca","transacao","recomendacao"}
if set(d.keys()) != expected_top: errors.append(f"top keys: {set(d.keys())}")
for k in ("seguro_garantia","fianca"):
    if set(d[k].keys()) != {"valor_garantido","custo_anual"}: errors.append(f"{k} keys")
if set(d["transacao"].keys()) != {"base","desconto_estimado","observacao"}: errors.append("transacao keys")

# 2) Arithmetic anchors
b = d["valor_remanescente_atualizado"]            # 591000
vg = 591000*1.30
assert b==591000
assert d["seguro_garantia"]["valor_garantido"]==768300==vg
assert abs(d["seguro_garantia"]["custo_anual"]-11524.50)<0.01     # 768300*0.015
assert abs(d["fianca"]["custo_anual"]-23049.00)<0.01              # 768300*0.03
assert d["transacao"]["base"]==591000
assert d["transacao"]["desconto_estimado"]==184392               # 283680*0.65
assert 230490+53190==283680 and round(283680*0.65)==184392 and 591000-184392==406608
assert round(283680*0.70)==198576 and 591000-198576==392424
assert 307320+230490+53190==591000
assert round(768300*0.008,2)==6146.40 and round(768300*0.02,2)==15366.00
# seguro <= metade da fiança (parelho por faixa: dobro exato)
assert 11524.50==23049.00/2 and 6146.40*2.5==15366.00

# 3) New wording present; old wording absent
must_have = ["metade ou menos","fiança prevista na LEF (art. 9º, II) é a bancária","condição de mercado, não regra dos autos"]
must_not  = ["fiador idôneo","menos da metade","seguro-fiança","edital da fixtures"]
for s in must_have:
    if s not in raw: errors.append(f"JSON missing: {s}")
for s in must_not:
    if s in raw: errors.append(f"JSON still contains: {s}")

# 4) Companion note + control files
note = open('sessao5/nota_ao_cliente.md', encoding='utf-8').read()
for s in ["Fiança bancária (LEF art. 9º, II) | 2%","Portaria PGFN 6.757/2022 e edital vigente"]:
    if s not in note: errors.append(f"nota missing: {s}")
for s in ["seguro-fiança","edital da fixtures"]:
    if s in note: errors.append(f"nota still contains: {s}")

st = open('STATUS.md', encoding='utf-8').read()
q  = open('QUESTIONS.md', encoding='utf-8').read()
if "só até R$ 84.000,00 alcançam os créditos vivos" not in st: errors.append("STATUS reconciliação ausente")
if "só o DARF do 1T/2021 (até 84 mil) alcança os créditos vivos" not in q: errors.append("QUESTIONS reconciliação ausente")

print("ERRORS:" if errors else "AUDIT OK — JSON válido, schema exato, 15+ âncoras aritméticas OK, redações corrigidas presentes, antigas ausentes, reconciliações 145k→84k aplicadas nos dois arquivos de controle.")
for e in errors: print(" -", e)
EOF

